import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Aprender hechizos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/learning-spells.md","filePath":"es/guide/magic/learning-spells.md"}'),n={name:"es/guide/magic/learning-spells.md"};function r(o,e,d,l,c,p){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="learning-spells" tabindex="-1">Aprender hechizos <a class="header-anchor" href="#learning-spells" aria-label="Enlace permanente a &quot;Aprender hechizos&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> <strong>Implementación:</strong> no se ha establecido que este rediseño esté implementado. <strong>Disponibilidad:</strong> no se ha establecido que esté disponible en juego. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Los Core Patterns son identidades de hechizos aprendidas; Magery mide su ejecución.</li><li>Maestros, libros y exploración pueden ampliar el conocimiento más allá de los umbrales de habilidad.</li><li>Los pergaminos de lanzamiento ordinarios no enseñan permanentemente; preparación y Familiarity siguen siendo conceptos distintos.</li></ul><p><a href="/Syrolands-Public/es/game-design/magic/spell-knowledge.html">Especificación completa del diseño</a></p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Función / límite Propuesto</th></tr></thead><tbody><tr><td>Capacidad</td><td>Conocer un hechizo y tener suficiente Magery para usarlo con fiabilidad son logros distintos. Alcanzar un umbral de habilidad no desbloquearía automáticamente un hechizo ni garantizaría el éxito.</td></tr><tr><td>Core Patterns y descubrimiento</td><td>Un Core Pattern es la identidad aprendida de un hechizo, como Fireball o Remove Curse a modo ilustrativo. Maestros, academias, culturas, ruinas, manuscritos, lugares mágicos, criaturas, rituales y experimentación podrían ampliar tu conocimiento. La enseñanza apropiada entre jugadores sigue siendo una posibilidad cuyas reglas aún deben diseñarse.</td></tr><tr><td>Práctica y preparación</td><td>Familiarity crece alrededor de patrones individuales sin consumir más límite de habilidades. Las escuelas más amplias y la especialización siguen siendo distintas. <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> determina el acceso preparado; un pergamino de lanzamiento ordinario no enseña permanentemente su hechizo.</td></tr><tr><td>Preguntas abiertas</td><td>La propuesta conserva magia útil desde el principio y descubrimiento a largo plazo. Los requisitos exactos de aprendizaje, el progreso y las restricciones siguen sin decidirse.</td></tr></tbody></table>',7)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
